def clean(df):
    df = df.copy()
    df["species"] = df["species"].str.strip().str.capitalize()
    df["species"] = df["species"].replace({"Adeile": "Adelie", "Gentto": "Gentoo", "Chinstarp": "Chinstrap"})
    df["body_mass_g"] = df["body_mass_g"].str.replace(",", "").astype(float)
    return df

def answer(df):
    return df.groupby("species")["body_mass_g"].sum().to_dict()
